package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ManagedVO;

class ManagedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of managed of observed source")
  void test_managed_value_holder_assign_plain_value() {
    Object holder = new Object();
    ManagedValueHolder<Object> value = new ManagedValueHolder<>(holder);
    Assertions.assertSame(holder, value.managed(true), "Setters must return the holder");
    Assertions.assertTrue(value.getManagedValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getManaged().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of managed of observed source")
  void test_managed_value_holder_assign_value_object() {
    Object holder = new Object();
    ManagedValueHolder<Object> value = new ManagedValueHolder<>(holder);
    ManagedVO vo = ManagedVO.from(true);
    Assertions.assertFalse(value.getManagedValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.managed(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getManagedValue().orElseThrow());
    Assertions.assertSame(holder, value.managed(Optional.empty()));
    Assertions.assertFalse(value.getManagedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.managed(Optional.of(vo)));
    Assertions.assertSame(vo, value.getManagedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of managed of observed source against the original")
  void test_managed_value_holder_read() {
    Object holder = new Object();
    ManagedValueHolder<Object> value = new ManagedValueHolder<>(holder);
    ManagedVO vo = ManagedVO.from(true);
    ManagedVO other = ManagedVO.from(true);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getManagedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readManaged(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readManaged(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.managed(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readManaged(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readManaged(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of managed of observed source")
  void test_managed_value_holder_unset() {
    Object holder = new Object();
    ManagedValueHolder<Object> value = new ManagedValueHolder<>(holder);
    ManagedVO vo = ManagedVO.from(true);
    value.managed(vo);
    Assertions.assertSame(holder, value.unsetManagedIfMatches("managed_other"));
    Assertions.assertTrue(value.getManagedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetManagedIfMatches("managed"));
    Assertions.assertFalse(value.getManagedValue().isPresent(),
        "The field name must clear the value");
    value.managed(vo);
    Assertions.assertSame(holder, value.unsetManaged());
    Assertions.assertFalse(value.getManagedValue().isPresent(), "Unset must clear the value");
  }
}
